INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('anger-and-self-restraint','anger-and-self-restraint','Managing Anger Through Islamic Teachings','ضبط الغضب','Qur’anic restraint and Prophetic advice','living_guidance','guidance','The Qur’an praises those who restrain anger and pardon others in 3:134. Sahih al-Bukhari 6116 reports the Prophet ﷺ repeatedly advising a questioner not to become angry. This introductory guide explains those texts and distinguishes moral teaching from advice about managing dangerous or persistent behaviour.','Source-linked general reference, not personalized fatwa or crisis support.','anger,angry,anger management,managing anger,controlling anger,how should I manage anger,self restraint,wrath,temper,losing temper,how to control anger','Scholarly editorial review pending.','editorial_draft','published','70');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('anger-and-self-restraint-s1','anger-and-self-restraint','Qur’anic perspective','scripture','Surah Ali Imran 3:134 describes those who control their anger and forgive people among those who do good. The verse connects restraint with ethical action rather than denying that people experience difficult emotions. It should be understood in its wider Qur’anic context.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('anger-and-self-restraint-s2','anger-and-self-restraint','Prophetic advice in a transmitted report','transmission','In Sahih al-Bukhari 6116, a man repeatedly asked for advice and the Prophet ﷺ repeatedly cautioned him against anger. The report communicates the importance of restraining harmful conduct when provoked. Its concise wording should not be expanded into an invented therapeutic procedure or an instruction to accept mistreatment.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('anger-and-self-restraint-s3','anger-and-self-restraint','Practical ethical application','practice','A person may choose not to retaliate immediately, avoid hurtful speech, apologise after causing harm, and seek a peaceful conversation when emotions have settled. These are practical suggestions drawn from the ethical theme, not verbatim Hadith instructions. Forgiveness need not mean abandoning personal safety or legitimate justice.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('anger-and-self-restraint-s4','anger-and-self-restraint','When further help is needed','safety','Persistent anger that threatens safety, abuse or serious distress may need professional support and appropriate protection. Religious encouragement toward restraint is not a substitute for mental health assessment, emergency help, or safeguards against violence. Juristic questions about redress and rights require a qualified scholar.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('anger-and-self-restraint-r1','anger-and-self-restraint','quran','The Qur’an — Ali Imran','3:134','https://quran.com/3/134','Anger restraint and forgiveness','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('anger-and-self-restraint-r2','anger-and-self-restraint','hadith','Sahih al-Bukhari — Good Manners','6116','https://sunnah.com/bukhari:6116','Repeated Prophetic caution against anger','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('anger-and-self-restraint-r3','anger-and-self-restraint','quran','The Qur’an — Ali Imran','3:135','https://quran.com/3/135','Seeking forgiveness after wrongdoing','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('repentance-tawbah-in-islam','repentance-tawbah-in-islam','Tawbah: Repentance and Returning to Allah','التوبة والاستغفار','A Qur’an- and Sunnah-linked reference','living_guidance','guidance','Qur’an 39:53 instructs those who have wronged themselves not to despair of Allah’s mercy. Qur’an 3:135 describes remembering Allah and seeking forgiveness rather than knowingly persisting in wrongdoing. Sahih Muslim 2747a portrays the importance of a servant’s repentance. This guide is an overview, not a case-specific ruling.','Source-linked general reference, not personalized fatwa or crisis support.','repentance,tawbah,tauba,toba,istighfar,ask forgiveness,how to repent,what is repentance,return to Allah,forgiven sins,forgiveness after sin','Scholarly editorial review pending.','editorial_draft','published','71');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('repentance-tawbah-in-islam-s1','repentance-tawbah-in-islam','The Qur’anic invitation to return','scripture','Surah Az-Zumar 39:53 speaks to people who have wronged themselves and counsels against despairing of the mercy of Allah. Its message encourages turning back rather than concluding that forgiveness is unavailable. The verse should be read in context and does not remove accountability toward other people.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('repentance-tawbah-in-islam-s2','repentance-tawbah-in-islam','Forgiveness and conduct','scripture','Surah Ali Imran 3:135 mentions those who remember Allah after wronging themselves, seek forgiveness and do not knowingly persist in the wrong. This establishes a relationship between seeking mercy and changing conduct, but this short article does not attempt to resolve every legal distinction among types of wrongdoing.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('repentance-tawbah-in-islam-s3','repentance-tawbah-in-islam','The transmitted Prophetic encouragement','transmission','Sahih Muslim 2747a gives a narration illustrating Allah’s pleasure at a servant’s repentance, using an example of someone unexpectedly recovering a lost mount after a desperate search. The parable is attributed to the full Hadith record and should not be paraphrased as a guaranteed verdict on an individual''s case.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('repentance-tawbah-in-islam-s4','repentance-tawbah-in-islam','Practical next steps and limits','practice','Someone who wishes to repent may acknowledge the wrong, sincerely ask Allah for forgiveness, avoid continuing the wrongdoing, and consider how to make amends where another person has been harmed. These are introductory practical themes. Questions about restitution, criminal harm, family rights, or repeated compulsive behaviour require suitable scholarly or professional support.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('repentance-tawbah-in-islam-r1','repentance-tawbah-in-islam','quran','The Qur’an — Az-Zumar','39:53','https://quran.com/39/53','Mercy and hope after wrongdoing','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('repentance-tawbah-in-islam-r2','repentance-tawbah-in-islam','quran','The Qur’an — Ali Imran','3:135','https://quran.com/3/135','Seeking forgiveness and avoiding persistence','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('repentance-tawbah-in-islam-r3','repentance-tawbah-in-islam','hadith','Sahih Muslim — Repentance','2747a','https://sunnah.com/muslim:2747a','Parable encouraging repentance','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('family-relationships-kindness','family-relationships-kindness','Family Relationships: Compassion, Parents and Children','صلة الرحم والرحمة بالأسرة','Family ethics in the Qur’an and Sunnah','living_guidance','guidance','Qur’an 17:23 instructs respectful treatment of parents, while 30:21 speaks of affection and mercy between spouses. Sahih al-Bukhari 5997 records the Prophet ﷺ showing mercy toward a child. These sources illustrate complementary obligations of kindness, without answering every legal or safety question faced by families.','Source-linked general reference, not personalized fatwa or crisis support.','family relationships,family relationship,family duties,family in islam,parents and children,how to treat family,spouses and family,compassion to family,mercy to children,rights of parents','Scholarly editorial review pending.','editorial_draft','published','72');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('family-relationships-kindness-s1','family-relationships-kindness','Respect toward parents','scripture','Surah Al-Isra 17:23 brings respect for parents together with worship of Allah alone, and directs believers to speak honourably to elderly parents. This ethical teaching is important, but its application to harmful or unsafe family situations may require additional scholarly and safeguarding advice.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('family-relationships-kindness-s2','family-relationships-kindness','Affection and mercy between spouses','scripture','Surah Ar-Rum 30:21 describes the placing of affection and mercy between spouses. It presents a Qur’anic picture of marital companionship; the verse does not in isolation define every legal duty, contract issue, or remedy where a marriage becomes harmful.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('family-relationships-kindness-s3','family-relationships-kindness','Mercy in the Prophet’s conduct with children','transmission','Sahih al-Bukhari 5997 narrates the Prophet ﷺ showing affection to al-Hasan and addressing someone who said he had not kissed his children. The account underlines the place of mercy in family conduct. Specific rulings should be assessed using the complete source context rather than an isolated example.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('family-relationships-kindness-s4','family-relationships-kindness','Family care in everyday life','practice','Listening respectfully, protecting children from harm, sharing responsibility for care, and speaking with compassion are reasonable applications of these ethical themes. These are editorial examples, not direct quotations. Domestic abuse, violence, coercion or urgent child-safety issues demand appropriate protection and qualified assistance, not only advice to be patient.','4');
